with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the sambal ahead and reheat it just before frying the ikan bilis, the anchovies need to go in hot to stay crispy.","If the ikan bilis are very small, you don't need to clean them; just rinse and fry whole.","For less heat, remove some of the chilli seeds before pounding."],"id":"ac3ce7b1-2d8e-450b-a10d-83e48aa64593"},{"notes":["Dough can be made ahead and refrigerated for up to 24 hours. Bring to room temperature before rolling.","Cooked varenyky freeze well for up to 1 month. Reheat by boiling briefly in salted water until they float again, or pan-fry with the caramelised onions.","The filling is traditional, but varenyky are also delicious filled with fried cabbage and mushrooms, or with cherries and sugar for dessert.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"6f50339e-977c-4958-8a0d-a40446c6027d"},{"notes":["Light soup keeps in the fridge for up to 3 days and freezes well for a month. Just reheat gently on the stove.","If you can't find groundnut paste, smooth peanut butter works just fine.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"12b85923-7966-45c5-b4de-c6b257271707"},{"notes":["Make the filling up to 2 hours ahead and chill. Roll the börek just before frying.","If yufka dries out, cover unused sheets with a damp tea towel.","Leftover börek can be reheated in a 180°C oven for 5 minutes to crisp up again.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"steps":[{"text":"Heat 1 tbsp neutral oil in a large pan over medium-high heat. Add the chopped onion and cook, stirring, until softened and golden, about 4 minutes."},{"text":"Add the beef mince and cook, stirring to break it up, until browned through, about 6 minutes. Drain off any excess fat."},{"text":"Stir in the cumin, black pepper, salt and parsley. Remove from heat and let cool for 5 minutes."},{"text":"Fold in the crumbled cheese and stir to combine. Taste and adjust seasoning. Let the filling cool completely."},{"text":"Lay one sheet of yufka on a clean work surface. Place 3 tbsp of filling along one long edge, leaving a 2 cm border."},{"text":"Fold the sides in by about 2 cm on each end, then roll tightly away from you, keeping it as firm as you can. The roll should be about 10 cm long and shaped like a tight cylinder. Repeat with remaining yufka and filling."},{"text":"Heat neutral oil in a large, deep frying pan to 180°C (or until a small piece of yufka sizzles immediately when dropped in)."},{"text":"Carefully place 2 or 3 börek at a time into the hot oil, don't crowd the pan. Fry until deep golden brown all over, about 3 minutes, turning once halfway through."},{"text":"Transfer to a paper towel to drain. Serve hot."}],"id":"a0a5d421-deba-441d-a147-747a440f4127"},{"steps":[{"text":"Drain the soaked chickpeas well and grind them with the ginger and green chillies in a food processor until smooth, adding a little water if needed. The batter should be fine and creamy."},{"text":"Transfer to a bowl and stir in the salt and citric acid. Cover loosely with a kitchen towel or cling film and leave to ferment at room temperature for 8 to 12 hours, or overnight. The batter will become slightly fluffy and airy."},{"text":"Set up a steamer: fill a large pot with water and bring to a simmer. Oil a round cake tin or two loaf tins, or a microwave-safe dish if you prefer. Place them in a steamer basket or on a trivet inside the pot so they sit above the water."},{"text":"Add the bicarbonate of soda to the fermented batter and stir gently but thoroughly, this will make it light and spongy. Do this just before steaming, as it loses its effect if left to sit."},{"text":"Carefully pour the batter into the prepared tin(s). Cover with foil or a lid and steam for 15 to 20 minutes, until a skewer inserted into the centre comes out clean and the top feels springy."},{"text":"While the dhokla steams, make the tadka: heat the oil in a small pan over medium heat until hot. Add the mustard seeds and let them crackle and pop for 30 seconds, then add the curry leaves and asafoetida. Stir for another 10 seconds until fragrant."},{"text":"Remove the dhokla from the steamer and carefully run a knife around the edges to loosen it. Turn it out onto a serving plate or board. Immediately pour the hot tadka over the top, letting the oil and seeds soak in."},{"text":"Leave to cool for a few minutes, then cut into squares or wedges and serve warm with chutney if you like. Leftover dhokla can be wrapped and kept in the fridge for 3 to 4 days."}],"id":"9d9c3bee-c19c-40de-a21b-882ee36a1ea0"},{"notes":["The laksa paste is the backbone, a good quality one saves time. If you can't find tamarind paste, soak a ball of tamarind pulp in hot water for 10 minutes, then strain.","Make the broth first and it'll wait for you while you fry the tofu and fish cakes. The noodles should be cooked fresh just before serving.","Some people add prawns to this laksa. If you'd like them, toss in 200 g of cooked prawns if that's how you like it."],"id":"45f37739-4e11-446a-9dcd-7bb94bc279b6"},{"notes":["Makes a generous batch. Keeps in the fridge for up to 4 days or freezes well for a month.","If you can't find guajillo or ancho chillies, use 3–4 dried red chillies of any kind, the technique is what matters."],"id":"db7d5514-e686-4d29-9c68-c80cb3b94220"},{"notes":["If you prefer a thinner soup, add more stock or water before blending.","Make the crispy onion topping ahead and store in an airtight container, it keeps for 3 days and turns any soup into something special.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"7c9a7135-a8bd-474b-867e-a63e0de51d28"},{"diets":["pescatarian","no-gluten"],"notes":["The galette batter can be made up to 4 hours ahead and kept covered in the fridge. Bring to room temperature for 10 minutes before cooking.","Clean mussels well under cold running water, pulling away any beard. Discard any that are open and won't close when tapped.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Throw away any mussels or clams whose shells stay closed after cooking. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"903c37ff-8bb0-42e8-ac5f-0c7231417925"},{"notes":["Swap the corned beef for tinned tuna or cooked chicken if that's what you've got.","Serve over rice or with fresh bread to soak up the sauce.","Any leftover veg works here, carrots, green beans, capsicum, whatever's in the crisper."],"id":"1143f50b-ffdd-4a24-ac8b-0d382470fb07"},{"notes":["The dough can be made up to 4 hours ahead, wrapped and refrigerated. Let it come to room temperature before stretching.","The broth keeps for 3 days in the fridge and tastes even better the next day.","If you're nervous about pulling noodles, you can roll the final dough thin and cut it into thick strands instead, it won't be quite the same, but it'll still be good.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Make the dough: mix flour and salt in a bowl. Add warm water gradually, stirring with your fingers until a shaggy dough forms. Knead on a bench for 8–10 minutes until smooth and elastic. Cover and rest for 20 minutes."},{"text":"While the dough rests, make the broth: heat oil in a large pot over medium-high heat. Add beef pieces in batches and brown on all sides, about 6 minutes total. Remove and set aside."},{"text":"In the same pot, add onion, garlic, and ginger. Stir until fragrant, about 2 minutes. Add doubanjiang and stir constantly for 1 minute until it darkens slightly."},{"text":"Return beef to the pot. Add sichuan pepper, cloves, star anise, bay leaf, and dried chillies. Stir to coat, then pour in stock. Bring to a simmer, then reduce heat to low. Cover and cook for 45 minutes until beef is very tender."},{"text":"Season the broth with soy sauce and salt to taste. Keep warm on a low heat."},{"text":"Divide the rested dough into two equal pieces. Oil your hands and the bench. Take one piece and stretch it gently into a rough rectangle about 20 cm long."},{"text":"Fold the rectangle in half, then in half again (folding into quarters), and roll it loosely into a log. Repeat this process two more times, resting 5 minutes between each fold. This builds layers and develops the stretch."},{"text":"Bring a large pot of salted water to a boil. Take your final dough log and, holding each end, gently stretch it by pulling away from your body and up over your arm, then back down, this distributes the gluten evenly. Stretch and fold, stretch and fold, until the noodle is about 50 cm long and very thin."},{"text":"Pull the stretched noodle away from your arm and, using one fluid motion, lay it down into the boiling water. It will curl and coil, this is perfect. Repeat with the second piece of dough."},{"text":"The noodles will rise to the surface within 2–3 minutes. Let them cook for another 1–2 minutes until they're just tender, then use a strainer to carefully lift them into serving bowls."},{"text":"Pour hot broth into each bowl with the noodles. Top generously with coriander, spring onion, a drizzle of chilli oil, and white pepper."}],"id":"bc274cd3-d7d9-4f42-ab9c-aa7ec10ba49a"},{"notes":["The ragù freezes beautifully for up to three months. Make a double batch when you have time.","Fresh tagliatelle is essential here. If you can't find it, use dried pappardelle, cook it to packet instructions instead.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Heat the olive oil in a large, heavy-based pot over medium heat. Add the pancetta and cook, stirring, until the fat renders, about 4 minutes."},{"text":"Add the onion, carrot and celery. Cook, stirring often, until soft and golden, about 8 minutes. This is your soffritto, don't rush it."},{"text":"Increase the heat to medium-high. Add the beef and pork mince, breaking it up with a wooden spoon. Cook, stirring often, until the meat is no longer pink, about 10 minutes. Season with salt and pepper."},{"text":"Pour in the white wine and scrape the bottom of the pot to lift the browned bits. Let the wine reduce until nearly evaporated, about 5 minutes."},{"text":"Stir in the tomato paste and cook for 1 minute. Add the crushed tomatoes and stir well."},{"text":"Reduce the heat to low. The ragù should barely simmer, just occasional lazy bubbles. Cook uncovered for 2 hours, stirring every 15 minutes or so. The sauce will thicken and darken."},{"text":"Pour in the milk and stir well. Continue to simmer on low heat for another 1 hour, stirring occasionally. The sauce will be rich, thick and deep brown. Taste and adjust the salt and pepper."},{"text":"About 30 minutes before serving, bring a large pot of salted water to a boil. Cook the tagliatelle for 2 to 3 minutes, or until tender. Fresh pasta cooks fast."},{"text":"Drain the pasta, reserving a cup of pasta water. Toss the tagliatelle with the ragù in the pot, adding a splash of pasta water if needed to loosen it. Serve with freshly grated Parmesan."}],"id":"0825b0b4-4cb3-4e04-b487-57cbde067892"},{"notes":["This curry tastes even better the next day. Reheat gently on the stove or in the microwave until warm through.","Use any firm white fish you like, snapper, barramundi, bream or cod all work well. Avoid delicate fish that will fall apart.","Serve with steamed rice, appam, or flatbread to soak up the coconut broth.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a large pan over medium-high heat. When it shimmers, add the cumin and coriander seeds and toast, stirring constantly, until they release their fragrance and darken slightly, about 2 minutes. Watch them closely so they don't burn."},{"text":"Add the curry leaves, then the onion. Cook, stirring often, until the onion is soft and golden, about 8 minutes."},{"text":"Stir in the garlic, ginger and green chilli. Cook for another minute until fragrant."},{"text":"Add the tomatoes and cook, stirring occasionally, until they break down and the raw edge is gone, about 5 minutes."},{"text":"Pour in the coconut milk and stir well. Bring to a gentle simmer, then carefully place the fish pieces into the curry. Season with salt and cook until the fish is opaque and flakes easily."},{"text":"Simmer gently, uncovered, for 8–10 minutes, until the fish is cooked through and flakes easily. Do not stir aggressively or the fish will break apart; you can gently turn the pieces once if needed."},{"text":"Taste and adjust salt if needed. Serve hot, scattered with fresh coriander if you like, alongside steamed rice."}],"id":"11dab63b-78c0-46ee-a2c2-c7abf838c67f"},{"notes":["Pilau tastes even better the next day. Reheat gently with a splash of water.","If beef chuck is hard to find, use beef shin or any tough cut that braises well.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"9105b802-80fa-43cc-828c-f147d235a38b"},{"notes":["If you can't find fresh holy basil, Thai basil works fine, use the same amount. Regular basil will change the flavour but won't ruin it.","Prep everything before you start cooking: mince the garlic, slice the chillies, tear the basil, measure the sauce. Once the wok hits temperature, there's no time to stop.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Heat your wok on high heat until it's smoking hot, about 2 minutes."},{"text":"Add the oil, then immediately add the minced garlic and sliced chillies. Stir constantly for 30 seconds until fragrant."},{"text":"Add the pork mince and break it up with the spatula. Stir-fry, without stirring constantly, for 2–3 minutes until cooked through and starting to caramelize. You want colour on it."},{"text":"Add the fish sauce and palm sugar. Toss well for 30 seconds to combine."},{"text":"Pull the wok off the heat. Add the fresh holy basil leaves and fold through gently until just wilted and fragrant, don't let them brown."},{"text":"Transfer the rice to a bowl or plate. Top with the pad grapow moo. Garnish with fried garlic and a fried egg if you want the real street-stall experience."}],"id":"3f3b1c25-e662-4f68-8ee9-942c2bea7456"},{"notes":["Make the filling while the onion cooks, so everything comes together quickly.","Keep your hands wet when rolling, it stops the meat from sticking and makes shaping easier.","These freeze well raw; just add a couple of extra minutes to the cooking time straight from the freezer.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"99841bff-a1c6-4799-9739-34bba4852be3"},{"notes":["Tastes just as good at room temperature, perfect for setting out on the table while you cook other things.","You can add a pinch of smoked paprika or cumin if you want a little more flavour, but honestly, the simplicity is the point."],"steps":[{"text":"Heat the olive oil in a large frying pan over medium heat. Add the sliced garlic and cook, stirring gently, for about 1 minute until fragrant but not coloured."},{"text":"Add the drained chickpeas and stir to coat with the oil. Cook for 2 minutes, then add the chopped spinach in batches, stirring as it wilts into the pan, this will take about 4–5 minutes in total."},{"text":"Once all the spinach is wilted and the chickpeas are heated through, season with salt and black pepper to taste. Serve hot or at room temperature with a lemon wedge on the side if you like."}],"id":"8dad6e5e-6e0b-460e-a64c-eb64418a883f"},{"notes":["If you can't find fresh crab, use 400 g tinned crab or frozen crab meat, thawed.","The noodle batter can be made up to 2 hours ahead and refrigerated; let it come to room temperature before using.","A bánh canh press makes thick, even noodles, but a large-holed colander works just as well.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Make the noodle dough: Pour 100 ml boiling water over the tapioca starch in a bowl and stir well. Let it cool for 2 minutes. Add the salt, then gradually add cold water while stirring until the mixture is smooth and has the texture of thick pancake batter, it should be glossy and slightly translucent. Let it rest for 10 minutes."},{"text":"Bring a large pot of water (at least 2 litres) to a rolling boil. Working in batches, push the noodle batter through a large-holed colander or bánh canh press directly into the boiling water. The noodles should be thick and rope-like, about the width of a finger. Stir gently to prevent sticking. Boil for 3-4 minutes until they float and are tender but still chewy. Remove with a slotted spoon and set aside."},{"text":"For the broth, heat the chicken stock and water in a large pot over medium heat. Add the crushed garlic and simmer for 3 minutes until fragrant."},{"text":"Stir in the fish sauce, sugar and crab meat. Simmer for 5 minutes to warm through and let the crab flavour infuse. Taste and adjust with salt and white pepper."},{"text":"Divide the cooked noodles among four bowls. Pour the hot crab broth over each serving."},{"text":"Top each bowl with fresh coriander, spring onion, fried garlic and sliced chilli if using. Serve with a lime wedge on the side."}],"id":"d5bc89ff-5752-4927-9193-246450c7b6c0"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"60c65a28-57d4-4f40-a002-cc976680a473"},{"notes":["Use bone-in chicken thighs if you prefer, they stay juicier. Cut around the bone and into cubes.","Presoaking wooden skewers for 30 minutes prevents burning, but metal skewers work best and cook faster.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Thread the chicken cubes onto two metal skewers, leaving a small gap between each piece so they cook evenly until cooked through and golden. Pat dry with paper towel."},{"text":"Heat the neutral oil in a frying pan over medium-high heat until shimmering, about 1 minute."},{"text":"Place the skewers in the pan and cook without moving them for 4 minutes, until the bottom is golden and slightly charred."},{"text":"Turn the skewers and cook for another 4 minutes until golden on the second side."},{"text":"Turn once more and cook for 2–3 minutes, turning as needed, until the chicken is cooked through (no pink inside). The outside should be blistered and charred in patches."},{"text":"Transfer to a plate, season generously with salt, and serve immediately with lemon wedges to squeeze over."}],"id":"62da20d0-4993-4335-8d08-dcd4c146cb7a"},{"notes":["The chickpea curry can be made ahead and reheated gently; make the bread fresh just before serving for the best texture.","If your kitchen scales aren't handy, the bread dough works with about 2 cups flour, 1 tsp baking powder, 1 tsp salt, 1 tbsp oil, and ¾ cup warm water.","Doubles are best eaten fresh and hot, the contrast between the warm spiced chickpea and crispy-soft bread is half the magic."],"id":"a926503a-6e11-45b1-912b-b49cb551f5dc"},{"notes":["The syrup can be made an hour ahead and kept warm in a low oven or over a very low heat. It must be hot when you dip the koeksisters.","Make sure your oil is at the right temperature, if it's not hot enough, the koeksisters will be greasy instead of crisp.","Store cooled koeksisters in an airtight container for up to 2 days, though they're best fresh and warm.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the syrup first so it's ready when you need it. In a small saucepan, combine the sugar, water, ground ginger and cinnamon stick. Bring to the boil, stirring until the sugar dissolves, then reduce the heat and simmer for 5 minutes. Remove from the heat, stir in the lemon juice, and set aside. The syrup must stay hot."},{"text":"Sift the flour, baking powder and salt into a bowl. Rub in the cold butter with your fingertips until the mixture resembles breadcrumbs. Do this gently, you want the dough light, not worked."},{"text":"In a small jug, whisk the egg and milk together. Make a well in the centre of the dry ingredients and pour in the egg mixture. Mix gently with a fork until a soft dough forms. Do not knead. If it's too dry, add a few drops more milk."},{"text":"Turn the dough out onto a lightly floured surface and shape into a ball. Wrap in cling film and rest for 10 minutes."},{"text":"Roll the dough out thinly, about 3 mm thick. Using a sharp knife, cut into strips about 2 cm wide and 12 cm long."},{"text":"Take each strip and plait (braid) it gently, pinching the ends to seal. The plaits should be loose and airy."},{"text":"Heat the oil in a deep frying pan to 180°C (a cube of bread should brown in 30 seconds). Working in batches so you don't crowd the pan, carefully lower the plaited strips into the hot oil."},{"text":"Fry for about 1 minute on each side until deep golden. They should be crisp and light. Remove with a slotted spoon."},{"text":"Immediately dip each hot koeksister into the hot syrup, turning to coat all over. The syrup will cling and caramelize on the outside. Place on a rack or paper towel to cool and set."},{"text":"Serve warm or at room temperature."}],"id":"1bab1394-d507-45b9-a23d-6fddf5ca6041"},{"steps":[{"text":"Drain the soaked salt cod and check for any remaining small bones. Flake the cod roughly into bite-sized pieces by hand, don't cut it; the irregular shreds are essential to esqueixada."},{"text":"In a large bowl, combine the flaked salt cod, fresh tomatoes, red onion and olives. If using tinned tomatoes, drain well and add them too."},{"text":"Dress with the olive oil and red wine vinegar, tossing gently to combine. Taste and adjust seasoning with salt (go easy, the cod is already salty) and a good grind of black pepper."},{"text":"Let the salad rest at room temperature for 15 minutes, until the tomato juices have mingled with the dressing and the flavours meld, then scatter with parsley if you like and serve."}],"id":"2c77df1b-321f-4415-9663-9dffcf0c2160"},{"notes":["The pickled beetroot can be made a day ahead and keeps in the fridge for up to a week.","If you can't find waxy potatoes, use any small firm potatoes and cut them in half.","Frikadeller freeze well uncooked; shape and refrigerate on a tray for 30 minutes, then freeze in a bag for up to three months.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Start the pickled beetroot: layer the beetroot in a bowl. In a small saucepan, heat the vinegar, water, sugar, salt, pepper and bay leaf over medium heat, stirring until the sugar dissolves. Pour over the beetroot and let it cool while you cook the rest."},{"text":"For the caramelised onions, melt the butter in a large frying pan over medium-low heat. Add the sliced onions and salt, stirring often. Cook for 20 to 25 minutes, until very soft and golden; set aside."},{"text":"Meanwhile, start the potatoes: cut them into even-sized pieces and place in a pot of cold salted water. Bring to a boil and cook for 12 to 15 minutes, until tender."},{"text":"While the potatoes cook, make the meatballs. Mix the pork, beef, grated onion, milk, breadcrumbs, egg, salt and pepper gently with your hands until just combined, don't overwork. Shape into 12 to 16 balls about the size of a golf ball."},{"text":"Heat butter or oil in a large frying pan over medium heat. Working in batches if needed, cook the meatballs, turning gently, for 8 to 10 minutes total, until golden and cooked through."},{"text":"Drain the potatoes and return them to the pot. Add the butter and a pinch of salt, and toss gently to coat."},{"text":"Divide the potatoes among serving plates. Top with the meatballs and caramelised onions, then serve with the pickled beetroot on the side. Scatter with fresh dill if you like."}],"id":"4fe7221e-0b17-415c-95a4-4a128416a556"},{"notes":["Make ahead: Mix the dough and shape the arepas up to 2 hours before cooking, then refrigerate, bring to room temperature before cooking.","Swap: If you can't find queso de mano, fresh mozzarella or even mild cheddar works, though it won't be quite the same.","You can cook arepas on a griddle, heavy-bottomed frying pan, or a cast-iron frying pan, whatever you have. The sound and smell tell you more than the time does."],"steps":[{"text":"Mix the corn flour, warm water and salt in a bowl, stirring until you have a soft, moist dough. Let it rest for 2–3 minutes."},{"text":"Wet your hands. Divide the dough into 2 balls and gently flatten each into a thick disc about 8 cm across and 1 cm thick."},{"text":"Heat a griddle or heavy frying pan over medium heat. Once hot, place the arepas on the griddle."},{"text":"Cook for 6–7 minutes until the bottom is golden and crusty, then flip and cook the other side for another 6–7 minutes until both sides are golden and the arepa sounds hollow when tapped."},{"text":"Using a thin knife, carefully cut a pocket into the side of each warm arepa without splitting it open completely."},{"text":"Stuff each arepa with the cheese strips while the arepa is still warm, the residual heat will melt the cheese slightly. Serve immediately."}],"id":"cb1d0e4b-b92d-4a82-bfdc-7b03ed618a7a"},{"steps":[{"text":"Rinse the lentils and place in a saucepan with 500 ml water. Bring to the boil, then simmer for 12 minutes until just soft but not falling apart. Drain well and let cool slightly."},{"text":"In a large bowl, combine the warm lentils with the bulgur, diced onion, garlic, tomato paste, cumin, Aleppo pepper, cinnamon and parsley. Mix gently but thoroughly until it just comes together. Season with salt and pepper. Let sit for 10 minutes so the bulgur absorbs moisture."},{"text":"With damp hands, shape the mixture into oval meatballs about 4 cm long. Place on a plate."},{"text":"Heat a thin layer of oil in a large frying pan over medium-high heat. Once shimmering, carefully add the köfte in batches, don't crowd the pan."},{"text":"Fry for 3 to 4 minutes on each side until golden and crispy all over. Transfer to a plate lined with paper towel."},{"text":"Serve warm with lemon wedges and yoghurt on the side."}],"id":"17138177-55a2-4239-8f51-7d4e3d0af4fd"},{"steps":[{"text":"Heat the sesame oil in a large shallow pot or braising pan over medium heat."},{"text":"Add the shiitake mushrooms, cut side down, and let them sit undisturbed for 2 minutes until they begin to brown."},{"text":"Turn the mushrooms and cook for another 2 minutes, then pour in the soy sauce, sugar, and water."},{"text":"Bring to a gentle simmer, then lower the heat and braise, uncovered, for about 15 minutes, until the mushrooms are tender and the liquid has reduced by half."},{"text":"Taste and adjust the soy sauce or water as needed, the braise should taste rich but not overly salty, with a glossy, slightly thickened sauce and tender mushrooms."},{"text":"Scatter the spring onions over the top and cook for 1 minute, then transfer to a serving bowl."},{"text":"Finish with the toasted sesame seeds and a pinch of black pepper. Serve warm or at room temperature."}],"id":"b3ecfe71-a49e-4ac9-bb2a-ea3edc96383e"},{"notes":["Cook the rice in advance and cool quickly; reheat gently before serving if you like. You can marinate the tofu overnight.","Fried shallots keep in an airtight container for a week.","The marinade ingredients are flexible, add a pinch of chilli flakes or a splash of rice vinegar if you like."],"id":"7bd16276-d32b-4b2c-924c-8332fb44d4ba"},{"notes":["The cucumber salad can be made up to 2 hours ahead and kept in the fridge. Drain before serving.","Use the best-quality pâté and bacon you can find, this sandwich lives or dies by those two things.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages)."],"steps":[{"text":"Make the cucumber salad: toss the sliced cucumber with the vinegar, sugar, salt and pepper. Set aside for at least 10 minutes so the cucumbers soften and flavour the brine."},{"text":"While the cucumber sits, cook the bacon in a frying pan over medium-high heat until crispy, about 5–6 minutes. Transfer to a plate lined with paper towel."},{"text":"Lightly toast the rye bread until just crisp at the edges if you like it warm, or leave it as is."},{"text":"Spread each slice generously with pâté."},{"text":"Top each slice with 2 rashers of bacon, then a spoonful of the cucumber salad (drain off excess liquid first). Sprinkle with fresh dill if you have it, and a pinch of flaky salt."},{"text":"Serve straight away while the bacon is still warm."}],"id":"3bc678bc-9e47-4c66-a8a7-9d37469b7111"},{"notes":["The soup thickens considerably as it cools. Reheat gently with a little water if needed.","Make it a day ahead, the flavour improves overnight. Store in the fridge for up to 4 days."],"id":"ffc72f75-a873-4746-b046-207b26a72ca1"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;